<div class="modal" id="modal"><div class="modalbox"><div class="modal-head"><div><h2>Mulai Konsultasi</h2><p>Isi singkat kebutuhan Anda. Setelah kirim, Anda akan diarahkan ke WhatsApp JetDesain.</p></div><button class="close" onclick="closeModal()" aria-label="Tutup"><?php echo icon('close');?></button></div><form method="post"><div class="formgrid"><div class="field"><label>Nama</label><input name="name" required placeholder="Nama Anda"></div><div class="field"><label>No. WhatsApp</label><input name="phone" placeholder="08xxxxxxxxxx"></div><div class="field"><label>Layanan</label><select name="service" id="modalService"><option>Desain Rumah</option><option>Bangun Rumah</option><option>Renovasi</option><option>Interior</option><option>3D & Rendering</option><option>Konsultasi umum</option></select></div><div class="field"><label>Luas / ukuran</label><input name="area" placeholder="Contoh: 120 m²"></div><div class="field full"><label>Ceritakan kebutuhan Anda</label><textarea name="message" placeholder="Contoh: saya punya tanah 8x15 m dan ingin rumah 2 lantai..." ></textarea></div></div><div class="modal-actions"><button type="button" class="btn ghost" onclick="closeModal()">Batal</button><button class="btn" name="consult" value="1" style="flex:1">Lanjut ke WhatsApp <?php echo icon('arrow');?></button></div></form></div></div><div class="toast" id="toast">Proyek disimpan ke daftar favorit.</div>
<script>
const modal=document.getElementById('modal');
function openModal(service){modal.classList.add('show');document.body.classList.add('modal-open');if(service){const s=document.getElementById('modalService');[...s.options].forEach(o=>{if(o.text.toLowerCase().includes(service.toLowerCase().split(' ')[0]))s.value=o.text;});}}
function closeModal(){modal.classList.remove('show');document.body.classList.remove('modal-open')}
modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function filterProjects(){const q=document.getElementById('search').value.toLowerCase().trim();document.querySelectorAll('.project').forEach(p=>{p.classList.toggle('hide',q&&!p.dataset.search.includes(q))})}
document.querySelectorAll('.tab').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));tab.classList.add('active');const f=tab.dataset.filter;document.querySelectorAll('.project').forEach(p=>p.classList.toggle('hide',f!=='all'&&p.dataset.category!==f))}));
function favorite(btn){btn.style.color=btn.style.color==='rgb(7, 85, 217)'?'#344054':'#0755d9';showToast(btn.style.color==='#344054'?'':'Proyek disimpan ke daftar favorit.');}
function showToast(t){const x=document.getElementById('toast');x.textContent=t||'Disimpan';x.classList.add('show');setTimeout(()=>x.classList.remove('show'),1800)}
function showProject(name){showToast(name+' — detail proyek siap dibahas saat konsultasi.');setTimeout(()=>openModal('Desain'),450)}
function toggleFaq(btn){btn.parentElement.classList.toggle('open')}
function calculate(){const area=Math.max(10,Number(document.getElementById('calcArea').value)||100),type=document.getElementById('calcType').value,level=Number(document.getElementById('calcLevel').value);const rates={desain:[80000,140000],bangun:[6500000,9000000],renovasi:[3500000,6000000],interior:[1800000,3200000]};let [a,b]=rates[type];a*=level;b*=level;const low=area*a,high=area*b;const fmt=n=>{if(n>=1e9)return 'Rp '+(n/1e9).toFixed(2).replace('.',',')+' M';return 'Rp '+Math.round(n/1e6)+' Jt'};document.getElementById('budget').textContent=fmt(low)+' – '+fmt(high)}
calculate();
const sections=[...document.querySelectorAll('main section[id]')];const navLinks=[...document.querySelectorAll('.bottom a')];window.addEventListener('scroll',()=>{let current='home';sections.forEach(s=>{if(scrollY>=s.offsetTop-160)current=s.id});navLinks.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+current))},{passive:true});
</script></body></html>